'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={status:'Ativo',commands:['Assalto','Perdeu','Socorro'],selected:0,sequence:0,logs:[],message:'Este celular tem uma história. Obrigado por ajudar a devolvê-lo.',contact:'(00) 90000-0000',plan:null,period:'Mensal',contactName:'Marina Costa',contactVerified:false,screen:'Dashboard',protection:true};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('sentinela-demo-v1')||'{}')};if(!Array.isArray(state.commands)||!Array.isArray(state.logs))state={...defaults};}catch{state={...defaults}}let busy=false,step=0,panel='Visão geral',mode=0,recovery='E-mail',recoveryStep=0,timer,alarmTimer,audio,oscillator,zoom=1;
const steps=['Comando de emergência reconhecido','Protocolo de proteção ativado','Tela bloqueada na simulação','Localização fictícia registrada','Alerta simulado para Marina Costa','Painel de recuperação atualizado'];
function save(){try{localStorage.setItem('sentinela-demo-v1',JSON.stringify(state))}catch{}}
function log(action){state.logs.unshift({action,time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})});state.logs=state.logs.slice(0,30);save()}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function shell(content,screen='Dashboard',nav=true){return `<div class="screen"><div class="statusbar"><span>9:41</span><span class="island"></span><span>▴ ▰</span></div><div class="phone-content reveal">${content}</div>${nav?`<div class="phone-bottom">${['Dashboard','Localização','Contatos','Perfil'].map((x,i)=>`<button data-screen="${x}" class="${screen===x?'active':''}">${['◈','⌖','♧','◎'][i]}<br>${x==='Dashboard'?'Início':x}</button>`).join('')}</div>`:''}</div>`}
function dashboard(){const protectedState=['Protegido','Perdido'].includes(state.status);return `<div class="phone-brand">◈ SENTINELA <span style="float:right;font-size:8px">DEMO</span></div><div class="phone-info"><span>Olá, Alex.</span><span>Seu dispositivo ↗</span></div><div class="phone-status ${protectedState?'locked':''}"><div class="shield-ring"><div class="shield">${protectedState?'⌑':'✓'}</div></div><h3>${state.status==='Ativo'?(state.protection?'Você está protegido.':'Proteção pausada.'):state.status==='Protegido'?'Protocolo ativado.':state.status==='Perdido'?'Modo perdido.':'Acesso recuperado.'}</h3><p>${protectedState?'Proteção visual demonstrativa ativada.':'Mais tranquilidade para seguir seu dia.'}</p><span class="badge">${esc(state.status.toUpperCase())} · SIMULAÇÃO</span></div><div class="phone-row"><span>⌖ Última localização<br><small>Jardim Aurora · Cidade fictícia</small></span><span>↗</span></div><div class="phone-row"><span>♧ Contato autorizado<br><small>${esc(state.contactName)}</small></span><span class="dot"></span></div><button class="primary full" data-action="incident">Testar proteção ↗</button>`}
function renderPhones(){ $('#heroPhone').innerHTML=shell(dashboard());$('#simPhone').innerHTML=shell(busy?`<div class="eyebrow">PROTOCOLO EM ANDAMENTO</div><div class="phone-status locked"><div class="shield-ring"><div class="shield">⌑</div></div><h3>${step>=3?'Tela protegida.':'Ativando proteção…'}</h3><p>${esc(steps[Math.max(0,step-1)])}</p><span class="badge">ETAPA ${step} DE 6 · DEMO</span></div><div class="phone-row">Localização ilustrativa <span>⌖</span></div><div class="phone-row">${step>=5?'Alerta simulado registrado':'Aguardando protocolo'}</div>`:dashboard());renderLostPhone();renderApp();}
function renderProtocol(){$('#protocol').innerHTML=steps.map((s,i)=>`<li class="${step>i?'done':''}">${s}</li>`).join('');$('#simulate').disabled=busy;$('#simulate').textContent=busy?'Simulação em andamento…':'Simular assalto ↗'}
let incidentTimer;function simulate(){if(busy)return;busy=true;step=0;state.status='Ativo';renderProtocol();renderPhones();incidentTimer=setInterval(()=>{step++;if(step===3)state.status='Protegido';renderProtocol();renderPhones();if(step>=6){clearInterval(incidentTimer);busy=false;state.status='Protegido';log('Incidente fictício: bloqueio, localização e alerta simulados');renderAll();toast('Protocolo concluído. O painel foi atualizado.')}},650)}
$('#simulate').onclick=simulate;$('#reset').onclick=()=>{clearInterval(incidentTimer);busy=false;step=0;state.status='Ativo';state.protection=true;log('Demonstração reiniciada');stopAlarm();renderAll();toast('Dispositivo fictício reiniciado.')};
const modes=[['Proteção contra assalto','Um acionamento discreto inicia uma resposta coordenada.','⌑','Reconhecer. Proteger. Registrar.','Acompanhe um incidente em uma linha do tempo visual.'],['Acionamento de emergência','Voz, atalhos ou aplicativo: explore possibilidades de ativação.','◉','Seu gesto, sua escolha.','Escolha um comando ou uma sequência demonstrativa.'],['Aparelho perdido','Uma mensagem de contato e um painel para acompanhar o retorno.','⌖','Um caminho de volta.','Ative o modo perdido e explore a recuperação.']];
function renderModes(){$('#modes').innerHTML=modes.map((m,i)=>`<button data-mode="${i}" class="${mode===i?'active':''}" aria-pressed="${mode===i}"><span>0${i+1}</span><div><strong>${m[0]}</strong><p>${m[1]}</p></div><span>↗</span></button>`).join('');$('#modeArt').innerHTML=`<div class="large-symbol reveal">${modes[mode][2]}</div><h3>${modes[mode][3]}</h3><p>${modes[mode][4]}</p><a class="text-link" href="#${['simulador','comandos','recuperacao'][mode]}">Explorar cenário ↗</a>`}
function renderCommands(){$('#commands').innerHTML=state.commands.length?state.commands.map((c,i)=>`<div class="command-row"><input type="radio" name="command" id="cmd${i}" value="${i}" ${state.selected===i?'checked':''}><label for="cmd${i}">${esc(c)}</label><button data-edit="${i}" aria-label="Editar ${esc(c)}">Editar</button><button data-delete="${i}" aria-label="Remover ${esc(c)}">×</button></div>`).join(''):'<p class="fine">Adicione uma frase para iniciar.</p>';$('#recognize').disabled=!state.commands.length;}
$('#commandForm').onsubmit=e=>{e.preventDefault();const value=$('#commandInput').value.trim();if(!value)return;if(state.commands.length>=8)return toast('Limite de 8 frases na demonstração.');if(state.commands.includes(value))return toast('Esta frase já está cadastrada.');state.commands.push(value);state.selected=state.commands.length-1;save();$('#commandInput').value='';renderCommands();toast('Frase adicionada.')};
$('#commands').onchange=e=>{state.selected=+e.target.value;save()};
$('#commands').onclick=e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete;if(edit!==undefined){openModal(`<div class="eyebrow">CONFIGURAÇÃO DEMONSTRATIVA</div><h2>Edite sua frase.</h2><form id="editCommand"><label for="editValue">Frase de emergência</label><input id="editValue" maxlength="40" value="${esc(state.commands[+edit])}" required><div class="actions"><button class="primary">Salvar frase</button></div></form>`);$('#editCommand').onsubmit=event=>{event.preventDefault();const v=$('#editValue').value.trim();if(!v)return;state.commands[+edit]=v;save();renderCommands();$('#modal').close()}}if(del!==undefined){state.commands.splice(+del,1);state.selected=Math.max(0,Math.min(state.selected,state.commands.length-1));save();renderCommands();toast('Frase removida.')}};
$('#wave').innerHTML=Array.from({length:45},(_,i)=>`<i style="--h:${8+Math.sin(i*.8)**2*30}px;--d:${i*.025}s"></i>`).join('');
$('#recognize').onclick=()=>{if(!state.commands.length)return;$('#wave').classList.add('listening');$('#recognize').disabled=true;toast(`Reconhecimento simulado: “${state.commands[state.selected]}”`);setTimeout(()=>{$('#wave').classList.remove('listening');$('#recognize').disabled=false;simulate();$('#simulador').scrollIntoView({behavior:'smooth'})},1200)};
const sequences=['Power três vezes','Power + Volume menos','Atalho de emergência compatível','Acionamento pelo aplicativo'];
function renderSequences(){$('#sequences').innerHTML=sequences.map((s,i)=>`<label class="sequence-choice"><input type="radio" name="sequence" value="${i}" ${state.sequence===i?'checked':''}>${s}</label>`).join('');$('#sequenceVisual').innerHTML=['◉ <span>× 3</span>','◉ <span>+</span> −','⌑ <span>ATALHO</span>','◈ <span>TOCAR PARA ACIONAR</span>'][state.sequence]}
$('#sequences').onchange=e=>{state.sequence=+e.target.value;save();renderSequences()};$('#previewSequence').onclick=()=>{const el=$('#sequenceVisual');el.classList.remove('pulse');void el.offsetWidth;el.classList.add('pulse');toast(`Sequência visual: ${sequences[state.sequence]}. Não intercepta botões reais.`)};
function mapHTML(){return `<div class="map" aria-label="Mapa ilustrativo do Jardim Aurora, cidade fictícia"><span class="map-label">JARDIM AURORA · MAPA ILUSTRATIVO</span><button class="map-marker" aria-label="Ver posição do dispositivo" data-action="marker"></button><div class="map-popup">◈ Dispositivo de Alex · posição fictícia</div><div class="map-controls"><button data-action="zoomOut" aria-label="Diminuir mapa">−</button><button data-action="zoomIn" aria-label="Ampliar mapa">+</button><button data-action="recenter" aria-label="Centralizar mapa">⌖</button></div></div>`}
const panelPages=['Visão geral','Localização','Incidentes','Contatos','Recuperação','Histórico de ações'];
function renderPanel(){$('#panelNav').innerHTML=panelPages.map((p,i)=>`<button data-panel="${p}" class="${panel===p?'active':''}">${['◈','⌖','⌑','♧','◎','↗'][i]} &nbsp; ${p}</button>`).join('');let content='';if(panel==='Visão geral'||panel==='Localização'){content=`<div class="panel-heading"><h3>${panel==='Visão geral'?'Seu dispositivo, em foco.':'Última posição conhecida.'}</h3><span class="badge">${esc(state.status.toUpperCase())}</span></div>${mapHTML()}<div class="stats"><div><b>Dispositivo de Alex</b>Modelo fictício · 84% bateria</div><div><b>Jardim Aurora</b>Posição ilustrativa · ${state.logs[0]?.time||'09:41'}</div><div><b>Conexão simulada</b>Último registro nesta sessão</div></div><div class="actions"><button class="primary" data-action="remoteProtect">Proteger remotamente</button><button class="outline" data-action="remoteRecover">Recuperar acesso</button><button class="outline" data-action="location">Atualizar posição demo</button></div>${panel==='Localização'?'<div class="activity"><span>09:35 · Praça das Oliveiras</span><small>Histórico fictício</small></div><div class="activity"><span>09:41 · Jardim Aurora</span><small>Histórico fictício</small></div>':''}`}
if(panel==='Incidentes'||panel==='Histórico de ações'){const logs=panel==='Incidentes'?state.logs.filter(l=>/Incidente|perdido|Proteção remota/.test(l.action)):state.logs;content=`<h3>${panel}</h3><p class="fine">Registros demonstrativos deste navegador.</p>${logs.length?logs.map(l=>`<div class="activity"><span>${esc(l.action)}</span><small>${esc(l.time)} · DEMO</small></div>`).join(''):'<p>Nenhum registro ainda. Teste uma simulação.</p>'}`}
if(panel==='Contatos')content=`<h3>Pessoas autorizadas.</h3><p class="fine">Nenhum contato real será acionado.</p><div class="activity"><span>${esc(state.contactName)}<br><small>Pessoa de confiança · (00) 90000-0000</small></span><span class="badge">${state.contactVerified?'VALIDADO · DEMO':'FICTÍCIO'}</span></div><button class="outline" data-action="validateContact">Validar contato na demo</button>`;
if(panel==='Recuperação')content=`<h3>Recupere seu acesso.</h3><p>Use uma segunda etapa de validação. A voz isolada não libera o dispositivo.</p><div class="activity"><span>${state.status==='Recuperado'?'Solicitação demonstrativa concluída':'Nenhuma solicitação em andamento'}</span><span class="badge">DEMO</span></div><button class="primary" data-action="remoteRecover">Iniciar recuperação</button>`;
$('#panelContent').innerHTML=content;}
$('#panelNav').onclick=e=>{if(e.target.dataset.panel){panel=e.target.dataset.panel;renderPanel()}};
function renderLostPhone(){$('#lostPhone').innerHTML=shell(`<div class="phone-brand">◈ SENTINELA / DEMO</div><div class="lost-screen"><div class="large-symbol">⌖</div><div class="eyebrow" style="justify-content:center">MODO CELULAR PERDIDO</div><h3>Este celular<br>tem um lar.</h3><p>${esc(state.message)}</p><div class="phone-row" style="justify-content:center">${esc(state.contact)}</div><p>Contato fictício do proprietário.<br>Sem chamadas reais nesta demonstração.</p><button class="outline full" data-action="found">Encontrei este aparelho</button></div>`,'Perdido',false)}
$('#lostMessage').value=state.message;$('#lostContact').value=state.contact;
$('#lostForm').onsubmit=e=>{e.preventDefault();const msg=$('#lostMessage').value.trim(),contact=$('#lostContact').value.trim();if(!msg||!contact)return toast('Preencha a mensagem e o contato fictício.');state.message=msg;state.contact=contact;state.status='Perdido';log('Modo perdido ativado na demonstração');renderAll();toast('Mensagem aplicada ao aparelho fictício.')};
function stopAlarm(){if(oscillator){try{oscillator.stop()}catch{}oscillator=null}if(audio){audio.close();audio=null}clearTimeout(alarmTimer);$('#alarm').textContent='Ouvir alarme demonstrativo'}
$('#alarm').onclick=()=>{stopAlarm();try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return toast('Áudio não suportado neste navegador.');audio=new AudioContext();oscillator=audio.createOscillator();const gain=audio.createGain();gain.gain.value=.04;oscillator.connect(gain).connect(audio.destination);oscillator.type='sine';oscillator.frequency.value=660;oscillator.start();$('#alarm').textContent='Alarme demonstrativo tocando…';alarmTimer=setTimeout(stopAlarm,8000)}catch{toast('O navegador não permitiu iniciar o áudio.')}};$('#stopAlarm').onclick=()=>{stopAlarm();toast('Alarme silenciado.')};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAlarm()});
const methods=['E-mail','Número principal','Pessoa de confiança','Biometria / Face ID','Voz demonstrativa'];
function renderRecovery(){$('#recoveryMethods').innerHTML=methods.map(m=>`<button class="method ${m===recovery?'active':''}" data-method="${m}">${m} <span style="float:right">↗</span></button>`).join('');const voice=recovery==='Voz demonstrativa',bio=recovery==='Biometria / Face ID';$('#recoveryFlow').innerHTML=recoveryStep===2?`<div class="recovery-step reveal"><span class="badge">CONFIRMAÇÃO SIMULADA</span><h3 style="margin-top:22px">Controle retomado.</h3><p>Fluxo demonstrativo concluído. O sistema operacional e as contas reais permanecem inalterados.</p><button class="outline" data-action="newRecovery">Explorar outro método</button></div>`:recoveryStep===1?`<form class="recovery-step" id="codeForm"><span class="badge">ETAPA 2 / 2 · DEMO</span><h3 style="margin-top:20px">Confirme a segunda etapa.</h3><p class="fine">Nenhuma mensagem foi enviada. Use o código de demonstração <b>123456</b>.</p><label for="demoCode">Código demonstrativo</label><input id="demoCode" inputmode="numeric" pattern="123456" maxlength="6" placeholder="123456" required><button class="primary">Confirmar recuperação</button></form>`:`<form class="recovery-step" id="recoveryForm"><span class="badge">ETAPA 1 / 2 · DEMO</span><h3 style="margin-top:20px">${voice?'Reconhecer não é autenticar.':bio?'Sua biometria fica no seu aparelho.':'Uma nova forma de entrar.'}</h3><p class="fine">${voice?'A voz é apenas um sinal visual. Uma segunda etapa é obrigatória.':bio?'Face ID e biometria dependem do aplicativo nativo ou de passkeys. Aqui, apenas simulamos a etapa.':'Escolha um dado fictício para explorar a validação. Não há envio de mensagens.'}</p>${!voice&&!bio?`<label for="recoveryValue">${recovery==='E-mail'?'E-mail fictício':'Número fictício'}</label><input id="recoveryValue" value="${recovery==='E-mail'?'alex@example.com':'(00) 90000-0000'}" required>`:''}<button class="primary">${voice?'Simular reconhecimento':bio?'Simular biometria':'Continuar validação'} ↗</button></form>`;
if($('#recoveryForm'))$('#recoveryForm').onsubmit=e=>{e.preventDefault();recoveryStep=1;renderRecovery()};if($('#codeForm'))$('#codeForm').onsubmit=e=>{e.preventDefault();if($('#demoCode').value!=='123456')return toast('Use o código demonstrativo 123456.');recoveryStep=2;state.status='Recuperado';log(`Recuperação simulada por ${recovery} + segunda etapa`);renderAll();toast('Recuperação demonstrativa concluída.')};}
$('#recoveryMethods').onclick=e=>{const method=e.target.closest('[data-method]');if(method){recovery=method.dataset.method;recoveryStep=0;renderRecovery()}};
const screens=['Splash','Onboarding','Cadastro','Login','Dashboard','Proteção','Comandos','Contatos','Dispositivos','Localização','Incidentes','Segurança','Assinatura','Perfil'];
function renderApp(){$('#screenMenu').innerHTML=screens.map(s=>`<button class="${s===state.screen?'active':''}" data-screen="${s}">${s}</button>`).join('');let c='',s=state.screen;
if(s==='Dashboard')c=dashboard();
if(s==='Splash')c=`<div class="phone-status" style="padding-top:85px"><div class="shield-ring"><div class="shield">S</div></div><h3>SENTINELA</h3><p>Seu controle, preservado.</p><button class="primary full" data-screen="Onboarding">Começar ↗</button></div>`;
if(s==='Onboarding')c=`<div class="eyebrow">BEM-VINDO / 01</div><h3>Mais presença.<br>Menos preocupação.</h3><div class="shield-ring"><div class="shield">✓</div></div><p>Configure seus comandos, escolha pessoas de confiança e explore a proteção.</p><button class="primary full" data-screen="Cadastro">Configurar minha demo</button><button class="text-link" data-screen="Login">Já tenho acesso</button>`;
if(s==='Cadastro'||s==='Login')c=`<div class="phone-brand">◈ SENTINELA / DEMO</div><h3>${s==='Cadastro'?'Seu primeiro passo.':'Bom ter você de volta.'}</h3><p>Use apenas os dados fictícios abaixo.</p><form id="appAuth">${s==='Cadastro'?'<label>Nome fictício<input value="Alex Costa" required></label>':''}<label>E-mail fictício<input type="email" value="alex@example.com" required></label><label>Senha demonstrativa<input type="password" value="demo123456" minlength="6" required></label><button class="primary full">${s==='Cadastro'?'Criar conta demo':'Entrar na demo'}</button></form><button class="text-link" data-screen="${s==='Cadastro'?'Login':'Cadastro'}">${s==='Cadastro'?'Já tenho conta':'Criar conta demo'}</button><button class="text-link" data-action="remoteRecover">Recuperar acesso</button>`;
if(s==='Proteção')c=`<div class="eyebrow">ESTADO DO DISPOSITIVO</div><h3>Sua proteção.</h3><div class="shield-ring"><div class="shield">✓</div></div><div class="phone-row">Status <b>${esc(state.status)}</b></div><button class="outline full" data-action="toggleProtection">${state.protection?'Pausar':'Ativar'} proteção demo</button><button class="primary full" style="margin-top:10px" data-action="incident">Simular emergência</button><p>Sem controle sobre o aparelho real.</p>`;
if(s==='Comandos')c=`<div class="eyebrow">SUA VOZ, SUA ESCOLHA</div><h3>Comandos.</h3>${state.commands.map((x,i)=>`<button class="phone-list-button" data-command="${i}">${state.selected===i?'◉':'○'} ${esc(x)}</button>`).join('')}<p>Edite e adicione frases na seção de comandos.</p><button class="outline full" data-action="goCommands">Gerenciar frases ↗</button>`;
if(s==='Contatos')c=`<div class="eyebrow">SUA REDE DE APOIO</div><h3>Pessoas de confiança.</h3><div class="phone-row">${esc(state.contactName)}<br>Contato fictício</div><form id="contactForm"><label>Nome demonstrativo<input id="contactName" maxlength="40" value="${esc(state.contactName)}" required></label><button class="primary full">Salvar contato demo</button></form><button class="text-link" data-action="validateContact">Validar contato</button><p>${state.contactVerified?'Contato validado na simulação.':'Validação ainda não simulada.'}</p>`;
if(s==='Dispositivos')c=`<div class="eyebrow">CONECTADO A VOCÊ</div><h3>Dispositivos.</h3><div class="phone-row">◈ Dispositivo de Alex<br><small>Principal · 84% bateria fictícia</small></div><div class="phone-row">Estado <b>${esc(state.status)}</b></div><button class="outline full" data-action="addDevice">Adicionar dispositivo demo</button><p>Família: até 5 aparelhos na proposta comercial.</p>`;
if(s==='Localização')c=`<div class="eyebrow">POSIÇÃO DEMONSTRATIVA</div><h3>Jardim Aurora.</h3>${mapHTML()}<p>Cidade fictícia. GPS do visitante desligado.</p><button class="outline full" data-action="location">Atualizar posição demo</button>`;
if(s==='Incidentes')c=`<div class="eyebrow">O QUE ACONTECEU</div><h3>Histórico.</h3>${state.logs.length?state.logs.slice(0,6).map(l=>`<div class="phone-row"><span>${esc(l.action)}<br><small>${l.time} · DEMO</small></span></div>`).join(''):'<p>Nenhum evento. Teste uma simulação.</p>'}`;
if(s==='Segurança')c=`<div class="eyebrow">IDENTIDADE PRESERVADA</div><h3>Segurança.</h3><div class="phone-row">Biometria / Face ID <span class="badge">NATIVO</span></div><p>Esta interface não acessa sua biometria. Explore um fluxo visual com segunda etapa.</p><button class="primary full" data-action="bioRecovery">Explorar recuperação</button><div class="phone-row">Voz isolada <small>Não libera acesso</small></div>`;
if(s==='Assinatura')c=`<div class="eyebrow">CUIDADO CONTÍNUO</div><h3>Seu plano.</h3><div class="phone-row">${esc(state.plan||'Nenhum selecionado')}<small>${esc(state.period)}</small></div><p>Valores em definição. Sem cobranças reais.</p>${['Essencial','Proteção Plus','Família'].map(p=>`<button class="phone-list-button" data-plan="${p}">${p} ↗</button>`).join('')}`;
if(s==='Perfil')c=`<div class="eyebrow">DO SEU JEITO</div><h3>Alex Costa.</h3><p>alex@example.com<br>Perfil fictício de demonstração.</p>${['Proteção','Segurança','Contatos','Assinatura'].map(p=>`<button class="phone-list-button" data-screen="${p}">${p} ↗</button>`).join('')}<button class="text-link" data-screen="Login">Sair da sessão demo</button>`;
$('#appPhone').innerHTML=shell(c,s,!['Splash','Onboarding','Cadastro','Login'].includes(s));if($('#appAuth'))$('#appAuth').onsubmit=e=>{e.preventDefault();setScreen('Dashboard');toast('Acesso fictício iniciado. Nenhuma conta real criada.')};if($('#contactForm'))$('#contactForm').onsubmit=e=>{e.preventDefault();state.contactName=$('#contactName').value.trim()||'Marina Costa';state.contactVerified=false;save();renderAll();toast('Contato fictício salvo.')};}
function setScreen(s){if(!screens.includes(s))return;state.screen=s;save();renderApp()}
const planData=[['Essencial','Uma base para seu dia a dia.',['1 dispositivo','Painel de recuperação','Contato de confiança','Histórico demonstrativo']],['Proteção Plus','Mais possibilidades de cuidado.',['1 dispositivo','Todos os recursos Essencial','Comandos e atalhos compatíveis','Gestão ampliada de incidentes']],['Família','Tranquilidade compartilhada.',['Até 5 dispositivos propostos','Recursos do Proteção Plus','Contatos por dispositivo','Visão familiar de proteção']]];
function renderPlans(){$('#plans').innerHTML=planData.map((p,i)=>`<article class="plan ${i===1?'featured':''}"><span class="badge">${i===1?'PROTEÇÃO EM DESTAQUE':'0'+(i+1)}</span><h3>${p[0]}</h3><p class="fine">${p[1]}</p><div class="price">Valor em definição</div><span class="fine">Assinatura ${state.period.toLowerCase()} · Proposta comercial</span><ul>${p[2].map(f=>`<li>${f}</li>`).join('')}</ul><button class="${i===1?'primary':'outline'} full" data-plan="${p[0]}">${state.plan===p[0]?'Selecionado · Explorar':'Explorar plano'} ↗</button></article>`).join('');$$('#billing button').forEach(b=>b.classList.toggle('selected',b.dataset.period===state.period))}
$('#billing').onclick=e=>{if(e.target.dataset.period){state.period=e.target.dataset.period;save();renderPlans();renderApp()}};
function openModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()};$('.modal-close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
function selectPlan(p){openModal(`<div class="eyebrow">ASSINATURA DEMONSTRATIVA</div><h2>${esc(p)}.</h2><p>Seu resumo de contratação.</p><div class="activity"><span>Ciclo</span><b>${esc(state.period)}</b></div><div class="activity"><span>Preço</span><b>Em definição</b></div><p class="fine">Recursos condicionados ao sistema e ao desenvolvimento do produto. Nenhum pagamento será solicitado.</p><form id="planForm"><label><input type="checkbox" required style="width:auto;margin-right:8px">Entendi que esta contratação é simulada.</label><div class="actions"><button class="primary">Confirmar seleção simulada ↗</button></div></form>`);$('#planForm').onsubmit=e=>{e.preventDefault();state.plan=p;log(`Plano ${p} selecionado · ${state.period} · sem cobrança`);renderAll();openModal(`<span class="badge">CONFIRMAÇÃO SIMULADA</span><h2 style="margin-top:22px">Sua escolha está salva.</h2><p>${esc(p)} · ${esc(state.period)}.<br>Nenhuma contratação ou cobrança real foi realizada.</p><button class="primary" id="closePlan">Continuar explorando ↗</button>`);$('#closePlan').onclick=()=>$('#modal').close()}}
const faq=[['Funciona no Android?','O conceito prevê uma versão Android. Bloqueio e restrições dependem de permissões administrativas e, em alguns casos, de um dispositivo gerenciado. O website simula essas possibilidades.'],['Funciona no iPhone?','A proposta inclui iPhone com os limites do iOS. Um aplicativo comum não pode bloquear globalmente todas as funções nem substituir o Buscar, Face ID ou o código do sistema.'],['Precisa de internet?','Alertas remotos e atualizações do painel precisam de conexão. Ações locais dependem da implementação nativa e das permissões. Esta apresentação não envia alertas.'],['Funciona com o celular desligado?','O Sentinela não garante rastreamento de aparelhos desligados. Buscar da Apple e Find Hub do Google podem localizar modelos compatíveis por suas próprias redes, conforme configurações, hardware e energia disponível.'],['Como configurar a proteção por voz?','Adicione e selecione frases na seção de comandos. O botão simula o reconhecimento sem abrir o microfone. Escuta permanente não é garantida e precisa de avaliação técnica por plataforma.'],['Como cadastrar contatos?','Na demonstração do aplicativo, abra Contatos, salve um nome fictício e simule a validação. Nenhum número ou pessoa será acionado.'],['Como recuperar o acesso?','Escolha e-mail, número ou pessoa de confiança. Use o código demonstrativo 123456 na segunda etapa. Voz ou biometria simuladas não autenticam sua conta real.'],['Posso proteger mais de um dispositivo?','O plano Família propõe até cinco dispositivos. A quantidade e as condições finais ainda serão definidas. O protótipo representa um dispositivo principal.'],['Como funciona a assinatura?','Explore os três planos e alterne mensal ou anual. A seleção fica neste navegador; preços estão em definição e não existe cobrança real.']];$('#faq').innerHTML=faq.map(f=>`<details><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('');
$('#interest').onclick=()=>{openModal(`<div class="eyebrow">VAMOS CONVERSAR SOBRE O FUTURO</div><h2>Proteção começa<br><em>com uma conversa.</em></h2><p>Conceito apresentado pela unitrixapp. Explore os cenários, escolha um plano e registre seu interesse apenas neste navegador.</p><form id="interestForm"><label><input type="checkbox" required style="width:auto;margin-right:8px">Quero acompanhar este conceito.</label><div class="actions"><button class="primary">Registrar interesse local</button></div></form><p class="fine">Sem envio de dados e sem inscrição em lista comercial.</p>`);$('#interestForm').onsubmit=e=>{e.preventDefault();log('Interesse comercial registrado localmente');$('#modal').close();toast('Interesse salvo neste navegador. Nenhuma mensagem enviada.')}};
function handleAction(action){if(action==='incident'){simulate();$('#simulador').scrollIntoView({behavior:'smooth'})}if(action==='remoteProtect'){state.status='Protegido';log('Proteção remota simulada');renderAll();toast('Proteção aplicada somente ao dispositivo fictício.')}if(action==='remoteRecover'||action==='bioRecovery'){recovery=action==='bioRecovery'?'Biometria / Face ID':'E-mail';recoveryStep=0;renderRecovery();$('#acesso').scrollIntoView({behavior:'smooth'});toast('Escolha um método e conclua a validação demonstrativa.')}if(action==='validateContact'){state.contactVerified=true;log('Contato fictício validado na simulação');renderAll();toast('Validação simulada. Nenhum SMS enviado.')}if(action==='location'){log('Posição fictícia atualizada: Jardim Aurora');renderPanel();toast('Posição ilustrativa atualizada. Sem GPS real.');$$('.map-marker').forEach(m=>m.classList.toggle('active'))}if(action==='marker')toast('Dispositivo de Alex · Jardim Aurora · localização fictícia.');if(action==='zoomIn'||action==='zoomOut'){zoom=Math.max(.7,Math.min(1.8,zoom+(action==='zoomIn'?.2:-.2)));$$('.map').forEach(m=>m.style.backgroundSize=`${zoom*100}% ${zoom*100}%`);toast(`Escala do mapa ilustrativo: ${Math.round(zoom*100)}%`)}if(action==='recenter'){$$('.map-marker').forEach(m=>m.classList.remove('active'));toast('Mapa centralizado no dispositivo fictício.')}if(action==='found')toast('Obrigado! Use o contato fictício exibido. Não há chamada real.');if(action==='newRecovery'){recoveryStep=0;renderRecovery()}if(action==='toggleProtection'){state.protection=!state.protection;log(state.protection?'Proteção demo retomada':'Proteção demo pausada');renderAll()}if(action==='goCommands')$('#comandos').scrollIntoView({behavior:'smooth'});if(action==='addDevice')openModal(`<span class="badge">DISPOSITIVO DEMONSTRATIVO</span><h2>Um cuidado<br><em>compartilhado.</em></h2><p>O conceito Família prevê até cinco dispositivos. Esta demonstração mantém um aparelho principal, sem pareamento real.</p><button class="primary" data-plan="Família">Explorar plano Família ↗</button>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-screen],[data-mode],[data-plan],[data-command]');if(!b)return;if(b.dataset.action)handleAction(b.dataset.action);if(b.dataset.screen){setScreen(b.dataset.screen);if(!b.closest('#aplicativo'))$('#aplicativo').scrollIntoView({behavior:'smooth'})}if(b.dataset.mode!==undefined){mode=+b.dataset.mode;renderModes()}if(b.dataset.plan)selectPlan(b.dataset.plan);if(b.dataset.command!==undefined){state.selected=+b.dataset.command;save();renderCommands();renderApp()}});
$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};$$('nav a').forEach(a=>a.onclick=()=>{$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});
function renderAll(){save();renderModes();renderProtocol();renderCommands();renderSequences();renderPhones();renderPanel();renderRecovery();renderPlans()};renderAll();

const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');revealObserver.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-head,.mode-layout,.config-grid,.web-panel,.plans,.closing h2').forEach(el=>{el.classList.add('scroll-reveal');revealObserver.observe(el)});
